export async function listTools() {
  return [
    {
      name: 'catalog_search',
      description: 'Search the catalog by name (case-insensitive) with pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search query matched case-insensitively against item names.' },
          offset: { type: 'integer', default: 0, minimum: 0, description: 'Number of results to skip.' },
          limit: { type: 'integer', default: 2, minimum: 1, maximum: 5, description: 'Maximum results to return per page (1-5).' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'catalog_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate query
  if (typeof args.query !== 'string') {
    throw new Error('query must be a string');
  }

  // Validate offset
  let offset = 0;
  if (args.offset !== undefined) {
    if (!Number.isInteger(args.offset) || args.offset < 0) {
      throw new Error('offset must be a non-negative integer');
    }
    offset = args.offset;
  }

  // Validate limit
  let limit = 2;
  if (args.limit !== undefined) {
    if (!Number.isInteger(args.limit) || args.limit < 1 || args.limit > 5) {
      throw new Error('limit must be an integer between 1 and 5');
    }
    limit = args.limit;
  }

  // Check for extra/unknown inputs
  const allowed = new Set(['query', 'offset', 'limit']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  // Search case-insensitively
  const q = args.query.toLowerCase();
  const matches = items.filter(item => item.name.toLowerCase().includes(q));

  const page = matches.slice(offset, offset + limit);
  const total = matches.length;
  const nextOffset = offset + limit < total ? offset + limit : null;

  const result = {
    rows: page,
    count: page.length,
    total,
    next_offset: nextOffset
  };

  return {
    content: [{ type: 'text', text: JSON.stringify(result) }]
  };
}
